import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

@Serializable
data class Bloc(val type: String, val text: String? = null)

@Serializable
data class Usage(val input_tokens: Int, val output_tokens: Int)

@Serializable
data class Reponse(val content: List<Bloc>, val stop_reason: String, val usage: Usage)

val lecteur = Json { ignoreUnknownKeys = true }

fun main() {
    val brut = """
        {
          "id": "msg_exemple",
          "role": "assistant",
          "content": [{"type": "text", "text": "Il garde l'état d'un écran."}],
          "stop_reason": "end_turn",
          "usage": {"input_tokens": 16, "output_tokens": 9}
        }
    """
    val reponse = lecteur.decodeFromString<Reponse>(brut)

    val texte = reponse.content.filter { it.type == "text" }.joinToString("") { it.text.orEmpty() }
    println(texte)
    println(reponse.stop_reason)
    println(reponse.usage.input_tokens + reponse.usage.output_tokens)
}

