data class Message(val role: String, val texte: String)

class Conversation {
    private val messages = mutableListOf<Message>()

    fun ajouter(role: String, texte: String) {
        messages += Message(role, texte)
    }

    fun requete(limite: Int): List<Message> = messages.takeLast(limite)
}

fun main() {
    val conversation = Conversation()
    conversation.ajouter("user", "Qu'est-ce qu'un Flow ?")
    conversation.ajouter("assistant", "Un flux de valeurs asynchrone.")
    conversation.ajouter("user", "Donne un exemple.")

    conversation.requete(2).forEach { println("${it.role} : ${it.texte}") }
}

