sealed interface EtatReponse {
    data object Vide : EtatReponse
    data object Reflexion : EtatReponse
    data class Pret(val texte: String) : EtatReponse
    data class Erreur(val message: String) : EtatReponse
}

class AssistantViewModel(private val assistant: Assistant) : ViewModel() {
    private val _etat = MutableStateFlow<EtatReponse>(EtatReponse.Vide)
    val etat: StateFlow<EtatReponse> = _etat.asStateFlow()

    fun demander(question: String) {
        if (question.isBlank()) return
        _etat.value = EtatReponse.Reflexion
        viewModelScope.launch {
            _etat.value = try {
                EtatReponse.Pret(assistant.repondre(question))
            } catch (e: IOException) {
                EtatReponse.Erreur("Connexion impossible. Réessayez.")
            }
        }
    }
}

