class Ecoute(context: Context, private val resultat: (String) -> Unit) {
    private val reconnaissance = SpeechRecognizer.createSpeechRecognizer(context)

    init {
        reconnaissance.setRecognitionListener(object : RecognitionListener {
            override fun onResults(resultats: Bundle?) {
                val textes = resultats?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                textes?.firstOrNull()?.let(resultat)
            }

            override fun onReadyForSpeech(params: Bundle?) = Unit
            override fun onBeginningOfSpeech() = Unit
            override fun onRmsChanged(rmsdB: Float) = Unit
            override fun onBufferReceived(buffer: ByteArray?) = Unit
            override fun onEndOfSpeech() = Unit
            override fun onError(erreur: Int) = Unit
            override fun onPartialResults(resultats: Bundle?) = Unit
            override fun onEvent(type: Int, params: Bundle?) = Unit
        })
    }

    fun demarrer() {
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, "fr-FR")
        }
        reconnaissance.startListening(intent)
    }

    fun liberer() = reconnaissance.destroy()
}

fun creerReconnaissance(context: Context): SpeechRecognizer =
    if (Build.VERSION.SDK_INT >= 31 && SpeechRecognizer.isOnDeviceRecognitionAvailable(context)) {
        SpeechRecognizer.createOnDeviceSpeechRecognizer(context)
    } else {
        SpeechRecognizer.createSpeechRecognizer(context)
    }

class Voix(context: Context) : TextToSpeech.OnInitListener {
    private val moteur = TextToSpeech(context, this)
    private var pret = false

    override fun onInit(statut: Int) {
        if (statut != TextToSpeech.SUCCESS) return
        val langue = moteur.setLanguage(Locale.FRENCH)
        pret = langue != TextToSpeech.LANG_MISSING_DATA &&
            langue != TextToSpeech.LANG_NOT_SUPPORTED
    }

    fun dire(texte: String) {
        if (pret) moteur.speak(texte, TextToSpeech.QUEUE_FLUSH, null, "lecture")
    }

    fun liberer() = moteur.shutdown()
}

