fun reduire(image: Bitmap, cote: Int): Bitmap {
    val echelle = cote.toFloat() / maxOf(image.width, image.height)
    if (echelle >= 1f) return image
    return Bitmap.createScaledBitmap(
        image,
        (image.width * echelle).toInt(),
        (image.height * echelle).toInt(),
        true,
    )
}

fun enBase64(image: Bitmap): String {
    val sortie = ByteArrayOutputStream()
    image.compress(Bitmap.CompressFormat.JPEG, 80, sortie)
    return Base64.encodeToString(sortie.toByteArray(), Base64.NO_WRAP)
}

